sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var ga =new GlideAjax("changepriority");
   ga.addParam("sysparm_name",'prioritychange');
   ga.addParam("current",newValue);
   ga.getXMLAnswer(short);

   function short(response){
	if(response == '1'){
		g_form.setValue("short_discription","critical");

	}
	else if(response == '2'){
		g_form.setValue("short_discription","moderate");
	}
	else if(response == '3'){
		g_form.setValue("short_discription","low");
	}
	else{
		g_form.setValue("short_discription","Not selected a valid priority");

	}

   }



   //Type appropriate comment here, and begin script below

}
